import { NextResponse } from 'next/server';
import connectDB from '../../../lib/mongodb.js';
import StructuredObservation from '../../../models/StructuredObservation.js';
import { requireAuth } from '../../../lib/auth.js';

/**
 * GET /api/observations
 * Returns structured observations generated by Gemini Computer Use.
 */
export async function GET(request) {
  try {
    const { session, errorResponse } = requireAuth(request);
    if (errorResponse) return errorResponse;

    await connectDB();
    const { searchParams } = new URL(request.url);
    const assessmentId = searchParams.get('assessmentId');
    const testRunId = searchParams.get('testRunId');
    const scenarioId = searchParams.get('scenarioId');

    const filter = {};
    if (assessmentId) filter.assessmentId = assessmentId;
    if (testRunId) filter.testRunId = testRunId;
    if (scenarioId) filter.scenarioId = scenarioId;

    const observations = await StructuredObservation.find(filter)
      .sort({ createdAt: -1 })
      .limit(100)
      .lean();

    return NextResponse.json({
      success: true,
      count: observations.length,
      observations,
    });
  } catch (err) {
    console.error('Error fetching observations:', err);
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}
